@startuml

class Customer {
  + name : string
  + phone : string
}

class Table {
  + number_of_seats : int
  + is_smoking : boolean
}

class Reservation {
  + day : date
  + time : time
  + number_of_people : int
}

class Waiter {
  + name : string
  + years_of_service : int
}

class Bill {
  + final_amount : double
}

class Dish {
  + name : string
  + unit_price : double
}

Customer "1" -- "*" Reservation
Reservation "*" -- "1..*" Table
Waiter "1" -- "*" Reservation
Reservation "1" -- "1" Bill
Bill "1" -- "*" Dish

@enduml

